// Puts everything the detector needs into one item, in the same shape the tests use.
const rows = name => $(name).all().map(i => i.json).filter(r => r && r.id !== undefined);
return [{ json: {
  mode: 'live',
  now: new Date().toISOString(),
  integrations: rows('Get integrations').filter(r => r.active !== false).map(r => ({ shop_id: r.shop_id, shop_name: r.shop_name })),
  events: rows('Get events of last 7 days').map(r => ({ shop_id: r.shop_id, received_at: r.received_at })),
  requests: rows('Get requests of last hour').map(r => ({ shop_id: r.shop_id, received_at: r.received_at, outcome: r.outcome, reason: r.reason })),
  alerts: rows('Get alerts of last 24 h').map(r => ({ shop_id: r.shop_id, alert_type: r.alert_type, created_at: r.created_at, status: r.status }))
} }];

// Rules only, no AI. All thresholds are here in one place.
const RULES = {
  BASELINE_DAYS: 7,              // history used to learn each integration's normal rhythm
  MIN_BASELINE_EVENTS: 20,       // fewer events than this = still learning, no silence alert
  SILENCE_MULTIPLIER: 3,         // silent if quiet for 3x the usual (90th percentile) gap...
  MIN_SILENCE_MINUTES: 60,       // ...and never for less than 60 minutes
  ERROR_WINDOW_MINUTES: 60,
  ERROR_RATE_THRESHOLD_PCT: 10,  // alert above 10% rejected requests
  MIN_REQUESTS_FOR_RATE: 10,     // ignore the rate when there are fewer requests than this
  REALERT_HOURS: 6               // no second alert of the same type while one is open
};
const MIN = 60000;
const fmt = d => new Date(d).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
const percentile = (arr, p) => { const s = [...arr].sort((a, b) => a - b); return s[Math.max(0, Math.ceil(p / 100 * s.length) - 1)]; };

return $input.all().map(item => {
  const input = item.json;
  const now = new Date(input.now).getTime();
  const results = [];
  const problems = [];

  for (const integ of input.integrations || []) {
    const shop = integ.shop_id;
    const times = (input.events || [])
      .filter(e => e.shop_id === shop)
      .map(e => new Date(e.received_at).getTime())
      .filter(t => t <= now && t >= now - RULES.BASELINE_DAYS * 1440 * MIN)
      .sort((a, b) => a - b);

    // --- silence ---
    let silence = null;
    let status = 'ok';
    let note = '';
    if (times.length === 0) {
      silence = { events_last_7_days: 0, last_event_at: 'none in the last 7 days' };
      note = 'no events in 7 days';
    } else {
      const last = times[times.length - 1];
      const minutesSilent = Math.floor((now - last) / MIN);
      if (times.length < RULES.MIN_BASELINE_EVENTS) {
        status = 'learning';
        note = times.length + ' events, need ' + RULES.MIN_BASELINE_EVENTS + ' to learn the rhythm';
      } else {
        const gaps = [];
        for (let i = 1; i < times.length; i++) gaps.push((times[i] - times[i - 1]) / MIN);
        const usual = Math.round(percentile(gaps, 90));
        const threshold = Math.max(RULES.MIN_SILENCE_MINUTES, RULES.SILENCE_MULTIPLIER * usual);
        note = 'quiet ' + minutesSilent + ' min, limit ' + threshold + ' min';
        if (minutesSilent > threshold) {
          silence = { minutes_silent: minutesSilent, hours_silent: Math.floor(minutesSilent / 60), events_last_7_days: times.length, last_event_at: fmt(last), usual_gap_minutes: usual, threshold_minutes: threshold };
        }
      }
    }

    // --- error spike ---
    const recent = (input.requests || []).filter(r => r.shop_id === shop && new Date(r.received_at).getTime() > now - RULES.ERROR_WINDOW_MINUTES * MIN && new Date(r.received_at).getTime() <= now);
    const accepted = recent.filter(r => r.outcome === 'accepted').length;
    const rejectedRows = recent.filter(r => String(r.outcome).startsWith('rejected'));
    const rejected = rejectedRows.length;
    const total = accepted + rejected; // duplicates are normal retries, not errors
    const rate = total ? Math.round(rejected / total * 1000) / 10 : 0;
    let spike = null;
    if (total >= RULES.MIN_REQUESTS_FOR_RATE && rate > RULES.ERROR_RATE_THRESHOLD_PCT) {
      const counts = {};
      for (const r of rejectedRows) { const k = r.outcome + ': ' + (r.reason || '').replace(/\(.*\)/, '').trim(); counts[k] = (counts[k] || 0) + 1; }
      const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
      spike = { window_minutes: RULES.ERROR_WINDOW_MINUTES, requests: total, rejected, error_rate_pct: rate, threshold_pct: RULES.ERROR_RATE_THRESHOLD_PCT, top_reason: top[0], top_reason_count: top[1] };
    }

    // --- one alert per problem, unless the same one is already open ---
    for (const [type, facts] of [['silence', silence], ['error_spike', spike]]) {
      if (!facts) continue;
      const open = (input.alerts || []).find(a => a.shop_id === shop && a.alert_type === type
        && ['pending review', 'approved'].includes(a.status)
        && new Date(a.created_at).getTime() > now - RULES.REALERT_HOURS * 60 * MIN);
      problems.push({ shop_id: shop, shop_name: integ.shop_name, alert_type: type, facts, skipped: !!open, skip_reason: open ? 'same alert already open since ' + fmt(open.created_at) : '' });
    }
    if (silence) status = 'silent';
    if (spike) status = status === 'silent' ? 'silent + error spike' : 'error spike';
    results.push({ shop_id: shop, status, note, error_rate_pct: rate, requests_last_hour: total });
  }
  return { json: { mode: input.mode, case_id: input.case_id || '', now: input.now, results, problems, new_alerts: problems.filter(p => !p.skipped).length } };
});

// Code checks the AI text before a person sees it.
// 1. Every number in the draft must come from the facts the rules computed.
// 2. The main number must be there. 3. No secrets, keys or signatures. 4. No other client's name.
// 5. CSM rules: no promised fix or deadline, no call or meeting, no free work or money. 6. Length.
// If a secret or key-like string is found, the draft is removed and no part of it is quoted in the notes.
const SHOPS = ['Mossbank Ceramics', 'Quillmoor Books', 'Tallowick Candles', 'shop_mossbank', 'shop_quillmoor', 'shop_tallowick'];
const realSecrets = [$vars.IHM_SECRET_MOSSBANK, $vars.IHM_SECRET_QUILLMOOR, $vars.IHM_SECRET_TALLOWICK].filter(s => s && s.length >= 8);
const SECRET_PATTERNS = [
  /v1=[0-9a-f]{8,}/i,
  /\b[0-9a-f]{32,}\b/i,
  /\b(sk|pk|rk|whsec)_[A-Za-z0-9]{6,}/,
  /\b[A-Za-z0-9+\/]{32,}={0,2}/
];
const PROMISE = /\b(we will|we'll|i will|i'll)\s+(fix|resolve|solve|repair|set up|reconfigure|handle|take care)\b|\bguarantee|\bas soon as possible\b|\bright away\b|\bwithin \d+\s*(minutes?|hours?|days?)\b/i;
const MEETING = /\b(call|meeting|meet|demo|zoom|jump on|hop on)\b/i;
const FREE = /\b(for free|free of charge|complimentary|no charge|no cost|on us|discount|refund)\b|(?<!feel )\bfree\b/i;
const nums = s => (String(s).match(/\d+(?:[.,]\d+)?/g) || []).map(n => n.replace(',', '.')).map(n => String(Number(n)));

return $input.all().map(item => {
  const d = item.json;
  const notes = [];
  if (d.parse_error) notes.push(d.parse_error);
  const text = (d.draft_subject || '') + '\n' + (d.draft_body || '');
  if (!d.parse_error && (!d.draft_subject || !d.draft_body)) notes.push('subject or body is empty');

  const secretHit = realSecrets.some(s => text.includes(s));
  const keyHit = SECRET_PATTERNS.some(p => p.test(text));
  if (secretHit) notes.push('contains a real signing secret');
  if (keyHit) notes.push('contains something that looks like a key or signature');
  const leak = secretHit || keyHit;

  const allowed = new Set(nums(JSON.stringify(d.facts || {})));
  const extra = [...new Set(nums(text))].filter(n => !allowed.has(n));
  if (extra.length) notes.push(leak ? 'numbers not in the facts (not listed because the text contains a secret or key)' : 'numbers not in the facts: ' + extra.join(', '));

  const f = d.facts || {};
  const main = d.alert_type === 'error_spike' ? [f.error_rate_pct, f.rejected] : [f.minutes_silent, f.hours_silent, f.last_event_at, f.events_last_7_days];
  const mainNums = main.filter(v => v !== undefined && v !== null).flatMap(v => nums(v));
  if (!d.parse_error && mainNums.length && !mainNums.some(n => nums(text).includes(n))) notes.push('main number missing');

  const others = SHOPS.filter(s => s !== d.shop_name && s !== d.shop_id && text.toLowerCase().includes(s.toLowerCase()));
  if (others.length) notes.push('mentions another client: ' + others.join(', '));

  if (PROMISE.test(text)) notes.push('promises a fix or a deadline');
  if (MEETING.test(text)) notes.push('asks for a call or meeting');
  if (FREE.test(text)) notes.push('offers free work or money');

  const words = (d.draft_body || '').trim().split(/\s+/).filter(Boolean).length;
  if (!d.parse_error && (words < 40 || words > 180)) notes.push('body has ' + words + ' words');

  const out = { ...d, check_passed: notes.length === 0, check_notes: notes.join('; ') };
  if (leak) { out.draft_subject = ''; out.draft_body = '[removed: the draft contained a secret or key]'; }
  return { json: out };
});

// One item per new alert. Code decides what the client should check; the AI only words it.
const HINTS = {
  silence: [
    'Is the webhook still enabled in the store admin?',
    'Did the store change the endpoint URL or move to a new domain or plugin version?',
    'Does the store webhook log show failed deliveries since the last successful event?'
  ],
  signature: [
    'Was the webhook signing secret changed or regenerated on the store side?',
    'Is a proxy or plugin changing the request body before it is sent?'
  ],
  timestamp: ['Is the clock on the sending server correct (time zone and NTP sync)?'],
  validation: ['Did a recent store update change the event format, for example a number now sent as text?']
};
const out = [];
for (const item of $input.all()) {
  for (const p of item.json.problems.filter(x => !x.skipped)) {
    let hints = HINTS.silence;
    if (p.alert_type === 'error_spike') {
      const r = p.facts.top_reason;
      hints = r.startsWith('rejected_signature') ? HINTS.signature : r.startsWith('rejected_timestamp') ? HINTS.timestamp : HINTS.validation;
    }
    out.push({ json: { mode: 'live', shop_id: p.shop_id, shop_name: p.shop_name, alert_type: p.alert_type, facts: p.facts, hints } });
  }
}
return out;

// Turns the model reply into subject + body. A failed or broken reply still becomes an alert, marked NO DRAFT.
const briefs = $('Prepare alert brief').all();
return $input.all().map((item, i) => {
  const b = briefs[i].json;
  const text = (item.json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n').replace(/```json|```/g, '').trim();
  let parsed = {};
  let parse_error = '';
  if (item.json.error) parse_error = 'AI call failed after retries';
  else { try { parsed = JSON.parse(text); } catch (e) { parse_error = 'AI reply is not valid JSON'; } }
  return { json: { ...b, draft_subject: String(parsed.subject || ''), draft_body: String(parsed.body || ''), parse_error } };
});
